{
  "project_id": "be06b5ef723b4e9b8995",
  "name": "setup_owner_scoped_semantic_search",
  "query": "create extension if not exists vector with schema extensions;

create table public.documents (
  id bigint generated always as identity primary key,
  owner_id uuid not null default auth.uid() references auth.users(id) on delete cascade,
  content text not null,
  embedding extensions.vector(384),
  created_at timestamptz not null default now(),
  constraint documents_content_not_blank check (length(btrim(content)) > 0)
);

comment on table public.documents is 'Knowledge-base documents with gte-small (384 dimension) embeddings.';
comment on column public.documents.embedding is 'Normalized gte-small embedding generated by the embedding Edge Function.';

create index documents_owner_id_idx on public.documents (owner_id);
create index documents_embedding_hnsw_idx
  on public.documents
  using hnsw (embedding vector_ip_ops);

alter table public.documents enable row level security;

create policy "Users can read their own documents"
on public.documents
for select
to authenticated
using ((select auth.uid()) = owner_id);

create policy "Users can create their own documents"
on public.documents
for insert
to authenticated
with check ((select auth.uid()) = owner_id);

create policy "Users can update their own documents"
on public.documents
for update
to authenticated
using ((select auth.uid()) = owner_id)
with check ((select auth.uid()) = owner_id);

create policy "Users can delete their own documents"
on public.documents
for delete
to authenticated
using ((select auth.uid()) = owner_id);

grant select, insert, update, delete on public.documents to authenticated;
grant usage, select on sequence public.documents_id_seq to authenticated;

create or replace function public.match_documents(
  query_embedding extensions.vector(384),
  match_threshold double precision,
  match_count integer
)
returns table (
  id bigint,
  content text,
  similarity double precision
)
language sql
stable
security invoker
set search_path = public, extensions
as $$
  select
    d.id,
    d.content,
    1 - (d.embedding <#> query_embedding) as similarity
  from public.documents as d
  where d.embedding is not null
    and d.embedding <#> query_embedding < -match_threshold
  order by d.embedding <#> query_embedding
  limit least(greatest(match_count, 1), 100);
$$;

revoke all on function public.match_documents(extensions.vector(384), double precision, integer) from public;
grant execute on function public.match_documents(extensions.vector(384), double precision, integer) to authenticated;"
}

